import{_ as t,o as e,c as s,a2 as r}from"./chunks/framework.CqGPl1zp.js";const p="/newx-doc/assets/%E6%96%B0%E5%BB%BA%E5%BA%94%E7%94%A8.DT8_bBEG.png",o="/newx-doc/assets/%E6%96%B0%E5%BB%BAAPI%E5%AF%86%E9%92%A5.DZB3CAtY.png",n="/newx-doc/assets/API%E5%AF%86%E9%92%A5.CXYe---X.png",i="/newx-doc/assets/%E6%A8%A1%E5%9E%8B%E9%85%8D%E7%BD%AE.DDg2HIFy.png",c="/newx-doc/assets/AI%E5%AF%B9%E8%AF%9D.DWOakbZQ.png",m=JSON.parse('{"title":"FastGPT 工作流","description":"","frontmatter":{},"headers":[],"relativePath":"ai/fastgpt.md","filePath":"ai/fastgpt.md","lastUpdated":null}'),l={name:"ai/fastgpt.md"};function d(h,a,f,g,_,A){return e(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="fastgpt-工作流" tabindex="-1">FastGPT 工作流 <a class="header-anchor" href="#fastgpt-工作流" aria-label="Permalink to &quot;FastGPT 工作流&quot;">​</a></h1><h2 id="_1-fastgpt-是什么" tabindex="-1">1. FastGPT 是什么？ <a class="header-anchor" href="#_1-fastgpt-是什么" aria-label="Permalink to &quot;1. FastGPT 是什么？&quot;">​</a></h2><p>FastGPT 是一个基于 LLM 大语言模型的知识库问答系统，提供开箱即用的数据处理、模型调用等能力。同时可以通过 Flow 可视化进行工作流编排，从而实现复杂的问答场景！</p><p>它的官网是 <a href="https://tryfastgpt.ai/" target="_blank" rel="noreferrer">https://tryfastgpt.ai/</a>，可直接申请使用。</p><p>同时，它也是个开源项目，地址是 <a href="https://github.com/labring/FastGPT" target="_blank" rel="noreferrer">https://github.com/labring/FastGPT</a>，可以自行部署。</p><h2 id="_2-如何接入" tabindex="-1">2. 如何接入？ <a class="header-anchor" href="#_2-如何接入" aria-label="Permalink to &quot;2. 如何接入？&quot;">​</a></h2><p>由于 FastGPT 的 <a href="https://doc.fastgpt.cn/docs/development/openapi/chat/#%E5%8F%91%E8%B5%B7%E5%AF%B9%E8%AF%9D" target="_blank" rel="noreferrer">对话接口</a> 兼容了 GPT 的接口，所以可以使用 <a href="./openai">《【模型接入】OpenAI》</a> 的方式，通过 OpenAIChatModel 进行接入。</p><p>下面，我们讲解下，如何把我们系统中的 <a href="./chat">《AI 对话聊天》</a> ，接入到 FastGPT 的工作台（简易应用、工作流、插件等）。</p><h3 id="_2-1-第一步-创建-fastgpt-应用" tabindex="-1">2.1 第一步：创建 FastGPT 应用 <a class="header-anchor" href="#_2-1-第一步-创建-fastgpt-应用" aria-label="Permalink to &quot;2.1 第一步：创建 FastGPT 应用&quot;">​</a></h3><p>① 在 <a href="https://cloud.fastgpt.cn/app/list" target="_blank" rel="noreferrer">https://cloud.fastgpt.cn/app/list</a> 工作台，点击【新建】按钮，创建一个应用。具体怎么创建，可见 <a href="https://doc.tryfastgpt.ai/docs/guide/workbench/" target="_blank" rel="noreferrer">https://doc.tryfastgpt.ai/docs/guide/workbench/</a> 文档。</p><p><img src="'+p+'" alt="新建应用"></p><p>② 点击应用，切换到【发布渠道】选项，再点击【API 访问】卡片，之后点击【新建】按钮，生成一个 API 密钥。</p><p><img src="'+o+'" alt="新建 API 密钥"></p><h3 id="_2-2-第二步-配置-api-密钥与模型" tabindex="-1">2.2 第二步：配置 API 密钥与模型 <a class="header-anchor" href="#_2-2-第二步-配置-api-密钥与模型" aria-label="Permalink to &quot;2.2 第二步：配置 API 密钥与模型&quot;">​</a></h3><p>① 在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，新建一个 FastGPT 的 API 密钥，填写上面的“密钥”，并设置 URL 为 <code>https://cloud.fastgpt.cn/api</code> 。如下图所示：</p><p><img src="'+n+'" alt="API 密钥"></p><p>② 在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; 模型配置] 菜单，新建一个 FastGPT 的聊天模型，填写上面的“模型名称” + “API 密钥” + “API URL”。如下图所示：</p><p><img src="'+i+'" alt="模型配置"></p><h3 id="_2-3-第三步-ai-对话聊天" tabindex="-1">2.3 第三步：AI 对话聊天 <a class="header-anchor" href="#_2-3-第三步-ai-对话聊天" aria-label="Permalink to &quot;2.3 第三步：AI 对话聊天&quot;">​</a></h3><p>在 [AI 大模型 -&gt; AI 对话] 菜单，选择 FastGPT 的聊天模型，即可开始对话。如下图所示：</p><p><img src="'+c+'" alt="AI 对话"></p><h2 id="_3-常见问题" tabindex="-1">3. 常见问题？ <a class="header-anchor" href="#_3-常见问题" aria-label="Permalink to &quot;3. 常见问题？&quot;">​</a></h2><p>① 如果你想使用 FastGPT 知识库接口，可参考 <a href="https://doc.fastgpt.cn/docs/development/openapi/dataset/" target="_blank" rel="noreferrer">https://doc.fastgpt.cn/docs/development/openapi/dataset/</a> 进行对接。</p><p>当然，我们系统已经提供了 <a href="./knowledge">《AI 知识库》</a> 功能。</p><p>② 如果使用 FastGPT 对话接口时，需要传递 <code>variables</code>、<code>responseChatItemId</code> 等参数，无法采用上述方式接入。</p><p>此时，只能参考 OpenAiChatModel 的源码，实现类似 FastGPTChatModel 的接入。</p>',26)])])}const b=t(l,[["render",d]]);export{m as __pageData,b as default};
